// Bank interrupt registers, with independent masks/force bits for both ARM cores.
export class PicoGPIOIRQ {
 constructor(runtime){this.r=runtime;const rp=runtime.rp;this.base=runtime.board.mcu==='RP2350'?0x40028000:0x40014000;this.raw=runtime.board.mcu==='RP2350'?0x230:0xf0;this.stride=runtime.board.mcu==='RP2350'?24:16;this.irq=runtime.board.mcu==='RP2350'?21:13;this.enable=[new Uint8Array(rp.gpio.length),new Uint8Array(rp.gpio.length)];this.force=this.enable.map(a=>new Uint8Array(a.length));rp.updateIOInterrupt=()=>this.update();const input=rp.gpioInputValueHasBeenSet.bind(rp);rp.gpioInputValueHasBeenSet=n=>{input(n);this.update();};}
 decode(address){const offset=((address>>>0)-this.base)&~0x3000;if((address>>>0)<this.base||(address>>>0)>=this.base+0x4000||offset<this.raw||offset>=this.raw+this.stride*7||(offset&3))return null;const group=Math.floor((offset-this.raw)/this.stride),start=((offset-this.raw)%this.stride)*2;return{group,start,op:((address-this.base)>>>12)&3};}
 read(address){const d=this.decode(address);if(!d)return null;let v=0;for(let i=0;i<8;i++){const p=d.start+i,g=this.r.rp.gpio[p];if(!g)continue;const core=Math.floor((d.group-1)/3),kind=(d.group-1)%3;const n=d.group===0?g.irqStatus:kind===0?this.enable[core][p]:kind===1?this.force[core][p]:(g.irqStatus&this.enable[core][p])|this.force[core][p];v|=(n&15)<<(i*4);}return v>>>0;}
 write(address,value){const d=this.decode(address);if(!d)return false;const core=Math.floor((d.group-1)/3),kind=(d.group-1)%3;for(let i=0;i<8;i++){const p=d.start+i,g=this.r.rp.gpio[p];if(!g)continue;const bits=(value>>>(i*4))&15;if(d.group===0){g.irqStatus&=~(bits&12);continue;}if(kind===2)continue;const a=kind===0?this.enable[core]:this.force[core],old=a[p];a[p]=d.op===1?old^bits:d.op===2?old|bits:d.op===3?old&~bits:bits;g.irqEnableMask=this.enable[0][p]|this.enable[1][p];g.irqForceMask=this.force[0][p]|this.force[1][p];}this.update();return true;}
 update(){const rp=this.r.rp;for(let core=0;core<2;core++){let asserted=false;for(let p=0;p<rp.gpio.length;p++)if((rp.gpio[p].irqStatus&this.enable[core][p])|this.force[core][p]){asserted=true;break;}rp.setInterruptCore(this.irq,asserted,core);}}
}
